/* Seekho Digital · Module 02–10 teaching content. All examples are fictional practice scenarios. */
(() => {
  const L = (title, short, minutes, intro, sections, example, task, check) => ({title,short,minutes,intro,sections,example,task,check});
  const Q = (q, options, correct, why) => ({q,options,correct,why});
  window.SEEKHO_COURSES = {
    2: {
      title:'Websites & Landing Pages', kicker:'BUILD A USEFUL ONLINE HOME', level:'Beginner', duration:'2–3 hours',
      outcome:'Plan a website that helps the right visitor understand an offer and take a useful next step.',
      project:{title:'Plan a small-business website',brief:'Create a clear five-page website plan for Maple Lane Home Bakery. The website should answer customer questions and make ordering feel easy.',deliverables:['One-sentence website purpose and primary audience','Simple page map with clear navigation','Homepage and product-page content outline','One focused call to action and trust checklist','Mobile and accessibility test notes'],steps:['Write the main visitor need before choosing a design.','Choose only the pages needed to answer that need.','Sketch the first screen and the next action.','Check every key detail on a phone.','Ask one person to complete the main task and note where they hesitate.']},
      glossary:[['Domain','The human-readable address people type to reach a website.'],['Hosting','A service that stores and serves website files.'],['HTTPS','An encrypted connection that helps protect data moving between a browser and a website.'],['Landing page','A focused page designed around one audience, offer and next action.'],['Navigation','The links and structure that help visitors move around a site.'],['CTA','Call to action: a clear prompt for the next step.'],['Wireframe','A simple structural sketch of a page before visual styling.'],['Accessibility','Designing so people with different abilities can use the site.']],
      lessons:[
        L('A website should solve a visitor problem','Purpose before design',15,'A website is not simply an online brochure. It is a tool that should help a particular person do something: understand an offer, compare options, ask a question, book, buy or get support.',[
          {heading:'Begin with the visitor and the job',body:'Before choosing colours, animations or a theme, finish this sentence: “A person visits this page because they need to ___.” Then decide what evidence or information would help them move forward. A bakery visitor may need the menu, prices, collection times, allergen information and a reliable way to order.',bullets:['Audience: who is most likely to use this page?','Need: what question or task brought them here?','Action: what is the most useful next step?','Proof: what makes the information trustworthy?']},
          {heading:'Choose one primary purpose per page',body:'A page can contain several links, but it should have one dominant job. A homepage introduces the business and routes visitors. A menu page helps people compare products. A contact page makes it easy to ask a question. When every button shouts “click me”, visitors have to do the planning themselves.',bullets:['Do not hide essential information behind clever labels.','Do not make visitors guess whether delivery is available.','Use specific link text such as “View breakfast boxes”, not “Click here”.']}
        ],{title:'Maple Lane example',body:'A customer has 90 seconds before work. They open the bakery website to check whether a breakfast box is available, how much it costs and whether collection is possible at 8:00 AM. A beautiful story about the founder cannot replace those answers.'},{title:'Write the website purpose',body:'Write one sentence describing the audience, their need and the action the website should support. Then list the top five questions the homepage must answer.',steps:['Name one primary audience.','Write the top task they came to complete.','List the information needed to complete it.','Choose one primary call to action.']},Q('What is the best first step when planning a website?', ['Choose a colour palette','Define the audience, their need and the page purpose','Add as many animations as possible'],1,'A clear purpose guides the structure, content and design. Decoration comes after the visitor task is understood.')),
        L('Domains, hosting and the path to a live site','How websites work',14,'A website address, the place its files live and the browser connection are different parts of the same experience. Understanding the basics helps you discuss a site without mixing up technical terms.',[
          {heading:'Domain, hosting and website files',body:'A domain is the memorable address, such as example.com. Hosting is the service that stores the website files and makes them available. The website itself is the collection of pages, images, styles and scripts. A domain points visitors towards the place serving the site.',bullets:['Domain: the address people remember.','Hosting: the service that stores and serves files.','DNS: the system that helps route a domain to the right server.','Browser: the app that requests and displays the page.']},
          {heading:'Why HTTPS and maintenance matter',body:'HTTPS encrypts information exchanged between the visitor and the website. It is essential for trust and especially important when forms or accounts collect information. A live website also needs updates, backups, working links, readable content and a process for correcting outdated details.',bullets:['Check that the site loads securely with HTTPS.','Use strong account passwords and multi-factor authentication where available.','Keep software and plugins maintained.','Back up important content and test recovery.']}
        ],{title:'Quick analogy',body:'Think of a website as a shop. The domain is the street address, hosting is the building where the shop operates, and the website files are the shelves, signs and products inside.'},{title:'Explain the route',body:'In plain language, explain what happens after someone types a domain into a browser. Include domain, DNS, hosting, HTTPS and the browser.',steps:['Start with the visitor entering the domain.','Explain that DNS helps find the right server.','Explain that hosting serves the website files.','Mention that HTTPS protects the connection.']},Q('Which statement is accurate?', ['Hosting is the memorable website address','A domain is the address; hosting stores and serves website files','HTTPS is a type of social media platform'],1,'The domain is the address, hosting stores and serves the site, and HTTPS protects the browser connection.')),
        L('Plan the page: hierarchy, content and calls to action','Page anatomy',18,'A useful page answers the visitor’s most important questions in a sensible order. It does not make people hunt for the price, purpose or next action.',[
          {heading:'A practical landing-page structure',body:'A focused landing page often includes a clear headline, a short explanation, the main benefit, supporting details, evidence, answers to common concerns and a specific call to action. The order changes with the offer, but the reader should not need to decode the page.',bullets:['Headline: say what the offer is and who it helps.','Supporting line: explain the main value.','Details: show features, price, availability and limitations.','Proof: use real reviews, credentials or demonstrations only when genuine.','CTA: describe the next step and what happens after it.']},
          {heading:'Features, benefits and proof',body:'A feature describes what something has. A benefit explains why that feature matters to the customer. “Freshly prepared each morning” is a feature; “a convenient breakfast ready for collection” explains its practical value. Proof must be accurate, current and relevant. Never invent testimonials, ratings, scarcity or customer counts.',bullets:['Feature: what is included.','Benefit: why the visitor may care.','Proof: what supports the claim.','Objection: what may stop the visitor from acting.']}
        ],{title:'Headline rewrite',body:'Weak: “Welcome to Maple Lane.” Stronger: “Breakfast boxes made for busy neighbourhood mornings.” The stronger line tells the visitor what is offered and gives a clue about its relevance.'},{title:'Sketch a landing page',body:'Create a page outline with six sections: headline, offer, benefits, details, trust and CTA. Add a note about the question each section answers.',steps:['Write one headline that names the offer.','Add three concrete benefits.','List price, availability and collection details.','Choose one CTA and explain what happens next.']},Q('Which CTA is clearest?', ['Submit','Click here','View breakfast boxes and collection times'],2,'Specific action text tells people what they will see or do. Clear expectations reduce uncertainty.')),
        L('Mobile UX, accessibility and testing','Make it usable',17,'A website that looks impressive on a large screen can still fail if text is tiny, buttons are difficult to tap or the form is confusing on a phone. Usability is part of marketing because it affects whether people can act.',[
          {heading:'Design for real use, not only screenshots',body:'Use readable text, clear spacing, visible focus states and buttons large enough to tap comfortably. Keep navigation understandable. Let content reflow on small screens and avoid requiring sideways scrolling for ordinary reading.',bullets:['Check the page at 320–375 CSS pixels wide.','Use real headings in a logical order.','Give images meaningful alternative text when they convey information.','Make form labels visible and errors understandable.','Do not communicate status through colour alone.']},
          {heading:'Test a task from beginning to end',body:'Ask someone to complete one realistic task without coaching them. Observe where they pause, misread a label or tap the wrong thing. A test is useful because it reveals friction, not because it produces a perfect score. Fix the biggest barrier first and repeat the task.',bullets:['Task: “Find the breakfast box price and collection time.”','Observe: where does the person look first?','Ask: what was unclear?','Improve: change one major barrier and test again.']}
        ],{title:'Accessibility is not an extra',body:'Captions, readable contrast, keyboard access and useful link text help people with disabilities and often improve the experience for everyone.'},{title:'Run a five-minute phone audit',body:'Open your site on a phone. Try to read the main heading, find contact details, use the main CTA and complete a form. Record three things that slowed you down.',steps:['Test a narrow screen.','Test with keyboard navigation if available.','Check text contrast and image alternatives.','Write the three highest-priority fixes.']},Q('What is the best way to find usability problems?', ['Assume visitors behave like the designer','Watch a person try a realistic task and note friction','Add more animations'],1,'A task-based test reveals real hesitation and misunderstanding. The next improvement should address the most important barrier.'))
      ],
      final:Q('A landing page receives visits but few enquiries. What should you inspect before buying more traffic?', ['The visitor task, page message, offer details, trust and form usability','Only the background colour','Whether the page has as many sections as competitors'],0,'More traffic does not repair a confusing page. First check relevance, clarity, proof and the path to action.')
    },
    3: {
      title:'SEO & Search Marketing', kicker:'HELP PEOPLE FIND USEFUL ANSWERS', level:'Beginner', duration:'3–4 hours', outcome:'Research what people search for, create helpful pages and understand the foundations of search visibility without promising rankings.',
      project:{title:'Create a beginner SEO plan',brief:'Build a small, realistic search plan for Maple Lane Home Bakery. Focus on local intent, useful pages and measurable improvements rather than ranking promises.',deliverables:['Audience and search-intent notes','Keyword/topic map for three pages','One optimised page outline','Local business information checklist','Measurement and review plan'],steps:['Collect real customer questions and search suggestions.','Group terms by intent, not just search volume.','Map one main topic to one useful page.','Improve page clarity and internal links.','Review Search Console and analytics after enough time has passed.']},
      glossary:[['SEO','Improving a website so search engines can understand it and people can find useful pages.'],['Search intent','The goal or need behind a search.'],['Crawl','When a search engine discovers and fetches a page.'],['Index','A search engine’s stored representation of a page that may be eligible to appear.'],['Title link','The clickable title shown for a result; search engines may generate it from page signals.'],['Canonical URL','A preferred URL indicated for duplicate or very similar pages.'],['Local SEO','Work that helps a business appear for relevant location-based searches.'],['Search Console','Google’s service for monitoring a site’s presence in Google Search.']],
      lessons:[
        L('Search starts with a person’s question','Intent before keywords',17,'SEO begins with understanding what a person is trying to find. A list of popular words is not a strategy unless you know the intent behind them and can create a page that genuinely helps.',[
          {heading:'Four useful intent patterns',body:'Search intent is the likely goal behind a query. Informational searches seek to learn. Navigational searches look for a particular site or brand. Commercial investigation compares options. Transactional searches indicate readiness to act. These categories overlap, so inspect the actual results and the context.',bullets:['Informational: “how to choose a breakfast box”.','Navigational: “Maple Lane menu”.','Commercial: “best breakfast boxes near me”.','Transactional: “order breakfast box delivery”.']},
          {heading:'Research topics from evidence',body:'Start with customer conversations, support questions, site search data, Search Console queries if available and search-result patterns. A keyword tool can provide estimates, but estimates are not guaranteed demand. Do not create a page just because a tool shows a number.',bullets:['Record the exact question in the customer’s words.','Identify location, urgency and comparison needs.','Check whether the business can honestly answer the query.','Choose one primary topic and related questions for each page.']}
        ],{title:'Maple Lane search example',body:'“Breakfast box” may be broad. “Breakfast box for office meeting in Jaipur” signals a different need. The page should clarify service area, minimum quantity, lead time, menu and how to enquire.'},{title:'Build a search-intent map',body:'Choose three real customer questions. Label the likely intent, what information the person needs and which page should answer it.',steps:['Write three exact queries.','Label each as learn, navigate, compare or act.','List the information needed to satisfy each query.','Match each query to one page or decide not to target it.']},Q('Why should you study intent before selecting keywords?', ['Because the same word always means the same thing','Because a page must satisfy the need behind the search, not simply repeat a phrase','Because search volume guarantees sales'],1,'Matching the searcher’s need is more useful than repeating a phrase. Search volume does not guarantee traffic or business results.')),
        L('How search engines discover and understand pages','Crawl, index, serve',16,'A page cannot appear in search simply because it exists. Search engines need to discover it, fetch it, understand it and decide whether it is eligible and useful for a particular query.',[
          {heading:'Crawling is not ranking',body:'Crawling is discovery and fetching. Indexing is storing and processing information about a page. Serving results is the later process of selecting results for a query. A site owner can help discovery with useful internal links, a sitemap and correct technical setup, but cannot force indexing or a position.',bullets:['A blocked page may not be crawlable.','A crawled page may still not be indexed.','An indexed page is not guaranteed to rank prominently.','A sitemap is a hint about pages you want discovered, not a ranking guarantee.']},
          {heading:'Technical foundations to check',body:'Use clear URLs, secure HTTPS, working internal links, mobile-friendly layouts and accurate page status codes. Avoid accidental noindex directives or robots rules that block important pages. Redirect retired URLs thoughtfully and keep canonical signals consistent where needed.',bullets:['Check important pages return a successful response.','Avoid duplicate versions where practical.','Keep navigation links crawlable and descriptive.','Use Search Console to inspect issues and page discovery.']}
        ],{title:'Simple analogy',body:'Crawling is like a librarian finding a book. Indexing is recording what the book contains. Serving is choosing which books answer a reader’s question. Being on the library shelf does not guarantee your book will be the first recommendation.'},{title:'Make a technical checklist',body:'Choose five important website URLs. Record whether each loads, has a unique purpose, is linked from another relevant page and is intended to be indexed.',steps:['List five key URLs.','Open each on mobile.','Check for broken links and confusing duplicates.','Review indexing status in Search Console when the site is connected.']},Q('Which statement about indexing is correct?', ['Submitting a sitemap guarantees first position','A crawled page is always indexed','Crawling, indexing and ranking are different processes'],2,'Discovery, indexing and result selection are related but distinct. No one action guarantees indexing or rankings.')),
        L('On-page SEO: make the page understandable','Titles, headings and links',18,'On-page SEO helps people and search engines understand a page. The aim is not to repeat a phrase everywhere; it is to make the topic, structure and value clear.',[
          {heading:'Write descriptive page elements',body:'A title link should describe the page accurately and distinguish it from other pages. Headings organise the content for readers. A concise description can help explain the page in a search snippet, although search engines may choose different text. URLs should be readable and stable.',bullets:['Give every important page a distinct, descriptive title.','Use one clear main heading that matches the page purpose.','Organise subtopics with meaningful headings.','Write naturally; do not stuff keywords.','Use descriptive internal link text.']},
          {heading:'Content quality and internal links',body:'Answer the question thoroughly enough for the reader to make progress. Use original examples, clear definitions, useful visuals and current facts. Link to related pages when it helps the reader continue. Remove filler and do not invent expertise, reviews or statistics.',bullets:['Show what the page covers near the beginning.','Use examples and steps where they clarify the topic.','Update outdated claims and links.','Link related pages in a context that makes sense.']}
        ],{title:'Before and after',body:'Weak title: “Home”. Better title: “Breakfast Boxes for Local Collection | Maple Lane”. The improved version identifies the offer and the business without promising a search position.'},{title:'Optimise one page',body:'Choose a real page and rewrite its title, main heading, opening paragraph and two internal links. Explain how each change helps a human visitor.',steps:['Write the page’s one-sentence purpose.','Create a unique descriptive title.','Make the H1 specific.','Add useful subheadings and contextual links.']},Q('Which is the healthier on-page SEO approach?', ['Repeat the keyword in every sentence','Use clear titles, useful structure and natural language','Hide text in the same colour as the background'],1,'Search-friendly pages should also be genuinely useful and accessible to people. Keyword stuffing and hidden text are not sound strategies.')),
        L('Local SEO and measuring search progress','Be useful in your area',18,'Local search helps people find nearby businesses and services. Accuracy matters: confusing addresses, hours or service areas can waste a visitor’s time and damage trust.',[
          {heading:'Make business information consistent',body:'A local business profile should use accurate business details and represent the real operation. Keep name, address or service area, phone, hours, categories, website and relevant photos current. Ask for honest reviews without buying, fabricating or selectively manipulating them.',bullets:['Use the real business name, not keyword-stuffed variations.','Keep opening hours and holiday changes accurate.','Describe the genuine service area.','Respond to feedback professionally and protect customer privacy.']},
          {heading:'Use the right measures',body:'Search performance is not one number. Impressions show appearances, clicks show visits from results and query/page reports reveal which topics attract attention. Leads and orders need separate measurement. A rise in clicks is not proof of profit; connect the data to the business goal.',bullets:['Track relevant queries and landing pages.','Check clicks and impressions over a consistent period.','Look for changes after technical or content edits.','Record leads and qualified outcomes separately.']}
        ],{title:'Maple Lane local checklist',body:'Before promoting a neighbourhood bakery, verify its service area, pickup point, opening hours, menu, phone number and website. A perfect keyword plan cannot compensate for incorrect practical information.'},{title:'Write a local visibility checklist',body:'Make a list of all public places where the business details appear. Mark which details need checking and who is responsible for updating them.',steps:['List the official website and business profiles.','Compare name, phone, address/service area and hours.','Check menu and ordering links.','Create a monthly accuracy reminder.']},Q('What should a local business do first if its public hours are wrong?', ['Run more ads','Correct the hours across the website and business profiles','Ask customers to ignore the listing'],1,'Accurate practical information is foundational. More promotion sends more people towards an avoidable source of confusion.'))
      ], final:Q('A blog post gets impressions but few clicks. Which is a sensible next investigation?', ['Check whether the page title and snippet clearly match the query and search intent','Add the same keyword 40 times','Buy links from unrelated sites'],0,'Review relevance, clarity and the result presentation. Do not use manipulative shortcuts or assume a single metric explains everything.')
    },
    4: {
      title:'Social Media & Brand Building', kicker:'BUILD RECOGNITION AND RELATIONSHIPS', level:'Beginner', duration:'3–4 hours', outcome:'Choose appropriate social platforms, build a recognisable brand and plan content that serves a real audience.',
      project:{title:'Create a social media starter strategy',brief:'Plan a four-week social presence for Maple Lane Home Bakery that can be maintained by a small team.',deliverables:['Audience and brand voice notes','Two or three content pillars','Four-week realistic calendar','Example post with a clear CTA','Community response and measurement rules'],steps:['Choose one priority audience and business goal.','Select platforms based on audience behaviour and team capacity.','Create repeatable content pillars.','Plan a sustainable posting rhythm.','Define how comments, messages and results will be handled.']},
      glossary:[['Brand identity','The visual and verbal elements used to express a brand.'],['Brand positioning','The intended place an offer occupies in the audience’s mind compared with alternatives.'],['Content pillar','A repeatable theme that organises content around audience needs.'],['Engagement','Meaningful audience interactions such as comments, saves, shares or replies.'],['Reach','The number of unique accounts or people shown content, as defined by a platform.'],['Impressions','The number of times content was displayed; repeats may be included.'],['Social listening','Monitoring conversations and feedback to understand audience needs.'],['Community management','The practice of responding, guiding conversations and maintaining a respectful space.']],
      lessons:[
        L('A brand is more than a logo','Meaning and consistency',16,'A brand is the set of expectations and associations people build through what a business says and does. A logo helps recognition, but the actual experience shapes trust.',[
          {heading:'Start with audience, promise and proof',body:'Define whom the business serves, what it wants to be known for and what experience it can reliably deliver. A brand promise should be realistic. If the business says “ready in five minutes”, the operating team must be able to support that claim.',bullets:['Audience: who should recognise the business?','Need: what matters to them?','Promise: what value can the business reliably provide?','Proof: what actions make the promise believable?']},
          {heading:'Build a recognisable voice',body:'A voice is the consistent personality in the language used by a brand. Define a few traits and examples. “Warm, clear and practical” is easier to use than “make it fun”. Avoid copying another brand’s distinctive identity or pretending to be a customer.',bullets:['Choose three voice traits.','Write a sentence that sounds on-brand.','Write one sentence that does not.','Use the same names and facts across channels.']}
        ],{title:'Maple Lane brand example',body:'The bakery chooses “warm, dependable and neighbourhood-focused”. It uses those traits in menu descriptions, order confirmations and replies—not only in its Instagram bio.'},{title:'Write a mini brand guide',body:'Describe the audience, one-sentence promise, three voice traits and three proof points. Include a phrase the brand should avoid because it overpromises.',steps:['Write the audience in a specific way.','Describe the promise without exaggeration.','Pick three voice traits.','List actions that prove the promise.']},Q('What creates a trustworthy brand?', ['A logo used on every image','A realistic promise supported by a consistent customer experience','A viral post'],1,'A visual identity helps recognition, but repeated experiences and honest claims build credibility.')),
        L('Choose platforms by fit, not popularity','Platform strategy',15,'A business does not need to publish everywhere. The useful platform is the one where the intended audience can be reached and where the team can deliver valuable content consistently.',[
          {heading:'Separate channel, platform and format',body:'A channel is the broad route, such as social media. A platform is a specific service, such as Instagram or LinkedIn. A format is how the content appears, such as a Reel, carousel, short video or story. Mixing these terms makes planning vague.',bullets:['Channel: social media.','Platform: Instagram.','Format: a short behind-the-scenes video.','Purpose: demonstrate how breakfast boxes are prepared.']},
          {heading:'Use a platform-fit scorecard',body:'Look at audience presence, content fit, intent, resource needs, customer support expectations and measurement. A platform may look popular but be a poor fit if the audience is not there or the business cannot maintain it.',bullets:['Can the audience realistically be reached here?','Does the format suit the message?','Can the team create content sustainably?','Can enquiries be answered promptly?','Can the business measure a useful outcome?']}
        ],{title:'Small team example',body:'A local bakery can start with one visual platform and a complete business profile rather than opening six accounts and leaving them inactive.'},{title:'Score three possible platforms',body:'Give each platform a 1–5 score for audience fit, content fit and team capacity. Explain the evidence behind each score; do not choose a platform only because it is fashionable.',steps:['List three possible platforms.','Score audience fit.','Score production and response capacity.','Choose one primary platform and one optional support channel.']},Q('What is the best platform-selection rule?', ['Use every platform because more is always better','Choose the platform with the highest follower count','Choose where audience needs, content fit and team capacity overlap'],2,'A sustainable strategy fits the audience and the team. More accounts can create more neglected work.')),
        L('Content pillars and a realistic calendar','Plan before posting',18,'A content calendar is useful when it helps the business publish consistently without repeating random promotions. Start with questions and audience needs, then organise ideas into a small number of themes.',[
          {heading:'Build three or four content pillars',body:'Pillars are repeatable themes. A bakery could use product/menu information, behind-the-scenes preparation, customer questions and neighbourhood stories. Each pillar should serve an audience need and support the brand promise.',bullets:['Helpful: answer a common question.','Proof: show a real process or product detail.','Human: introduce the people and place behind the business.','Action: explain ordering, collection or availability.']},
          {heading:'Plan a sustainable rhythm',body:'A calendar should specify the audience question, message, format, owner, publication date and intended action. Leave room for timely updates. Consistency means a reliable rhythm, not posting every day regardless of quality.',bullets:['Batch ideas before writing captions.','Reuse a strong idea in an appropriate new format.','Use real images and disclose relevant partnerships.','Review performance over a useful period, not after one post.']}
        ],{title:'One idea, several formats',body:'A post about the ingredients in a breakfast box can become a carousel explaining choices, a short preparation video and a FAQ answer. Adapt the information for each format instead of copying and pasting blindly.'},{title:'Draft a one-week calendar',body:'Create three posts. For each, write the audience question, content pillar, format, caption idea and CTA. Make sure all three posts are not sales promotions.',steps:['Choose three audience questions.','Match each question to a pillar.','Choose a suitable format.','Add the next step and content owner.']},Q('What makes a content pillar useful?', ['It is a theme connected to audience needs and business goals','It is a trending hashtag','It is a promise to post every hour'],0,'Pillars create a repeatable structure for relevant content. They should reflect audience needs, brand value and what the team can produce.')),
        L('Community, conversations and measurement','Respond and learn',17,'Social media is not only a publishing channel. It is also a place where people ask questions, share experiences and give feedback. A useful strategy plans for listening and responding.',[
          {heading:'Write response guidelines',body:'Set expectations for response time, tone, escalation and privacy. Thank people for useful feedback. Take personal order details out of public comments. Move sensitive conversations to an appropriate private channel, but do not ask for passwords or unnecessary personal data.',bullets:['Answer common questions with accurate information.','Correct mistakes without blaming the customer.','Escalate safety, payment or serious complaints.','Hide or report abuse according to a clear policy.']},
          {heading:'Measure outcomes, not vanity alone',body:'Reach and impressions help describe distribution. Comments, saves and shares can suggest interaction. Website visits, qualified enquiries and orders are closer to business outcomes. Define what each platform metric means and compare like with like.',bullets:['Set one primary objective.','Choose one or two supporting measures.','Record the date range and content type.','Learn what to change next—not just what got the most likes.']}
        ],{title:'Good moderation example',body:'A customer posts that collection details were unclear. The bakery thanks them, clarifies the correct process publicly and updates the website so future customers do not face the same confusion.'},{title:'Create a response playbook',body:'Write a sample response for a positive comment, a routine question and a complaint. Add a note explaining which issues should be escalated privately.',steps:['Choose the brand voice.','Draft a helpful positive reply.','Draft a factual answer to a question.','Draft an empathetic complaint acknowledgement and next step.']},Q('A customer shares an order number in a public comment. What is the sensible response?', ['Repeat the order details publicly','Ask for their account password','Move the conversation to a suitable private support channel and protect their information'],2,'Customer information should not be exposed. Use a secure and appropriate channel and request only necessary details.'))
      ], final:Q('A small business has limited time. Which social plan is most useful?', ['Six inactive accounts and daily generic posts','One or two well-chosen platforms, clear pillars and a sustainable response plan','Only promotional posts with no customer interaction'],1,'A realistic plan is better than an unmaintainable presence. Choose fit, quality and response capacity.')
    },
    5: {
      title:'Performance Marketing & Ads', kicker:'TEST, MEASURE AND IMPROVE RESPONSIBLY', level:'Beginner', duration:'3–4 hours', outcome:'Understand paid campaign structure, budget control, ad metrics and safe optimisation decisions.',
      project:{title:'Build a simulated paid campaign plan',brief:'Create a test plan for a fictional local breakfast-box campaign. No real ad account or spend is required.',deliverables:['Objective and conversion definition','Audience and location hypothesis','Campaign message and creative outline','Test budget and schedule','Measurement plan and stop conditions'],steps:['Choose one business objective and measurable action.','Check the offer and landing page before advertising.','Create a narrow, testable audience hypothesis.','Set a small affordable test budget and end date.','Review outcomes and document what the data can and cannot tell you.']},
      glossary:[['Impression','One display of an ad, as defined by the platform.'],['Click-through rate','Clicks divided by impressions, multiplied by 100.'],['CPC','Cost per click: spend divided by clicks.'],['CPM','Cost per thousand impressions, using the platform’s defined impression count.'],['CPA','Cost per acquisition or defined conversion.'],['ROAS','Attributed revenue divided by ad spend; it is not profit.'],['Frequency','Average number of times an ad was shown to a reached person, as defined by the platform.'],['Learning phase','A platform period in which delivery systems gather data; exact definitions vary by platform.']],
      lessons:[
        L('Choose the objective before the ad format','Goal and conversion',16,'Paid advertising can create attention, visits, leads or purchases. The campaign objective should reflect what the business needs and what the website or sales process can actually measure.',[
          {heading:'Translate a business goal into an ad objective',body:'“Grow the business” is too broad for a campaign. A more useful objective might be “generate qualified enquiries for weekday breakfast delivery within the service area”. Define what counts as a qualified enquiry before launching.',bullets:['Business goal: the outcome that matters to the organisation.','Campaign objective: the near-term result the campaign supports.','Conversion: the action counted, such as a submitted enquiry form.','Quality rule: the conditions that make an enquiry relevant.']},
          {heading:'Check readiness before paying for traffic',body:'Ads amplify the experience people land on. If the menu is unclear, the form fails on mobile or the business cannot fulfil orders, paid traffic may simply expose the problem faster. Test the whole path and set a maximum affordable spend.',bullets:['Offer, price and availability are confirmed.','Landing page and form work on a phone.','Tracking is tested.','A person is responsible for responding.','A clear budget cap and review date exist.']}
        ],{title:'Maple Lane campaign objective',body:'Instead of “get more likes”, the bakery chooses “receive 15 relevant breakfast-box enquiries from people in its service area during a four-week test”. This is a target for practice, not a forecast or guarantee.'},{title:'Write an objective and conversion rule',body:'Write the business outcome, campaign objective, conversion event and qualification rule. Explain how you will count duplicates or irrelevant submissions.',steps:['Name the business goal.','Choose the campaign outcome.','Define exactly what event counts.','Write the qualification rule.']},Q('What should be defined before selecting an ad format?', ['The business objective and conversion event','A trending colour','The number of emojis in the caption'],0,'The objective determines what success means and which campaign structure or measurement is appropriate.')),
        L('Campaign structure and audience hypotheses','Organise the test',17,'Ad platforms have different campaign structures, controls and naming conventions. The common planning idea is to organise a clear objective, audience or delivery approach, creative and measurement so the test can be understood.',[
          {heading:'Understand the basic layers',body:'Many platforms organise work into a campaign level, an ad group or ad set level, and individual ads. The labels and settings vary. The campaign typically holds the objective; the middle layer often controls audience, placement, schedule or budget; the ad contains the creative and message.',bullets:['Campaign: what outcome are you pursuing?','Ad set/group: who or where are you trying to reach and under what settings?','Ad: what message and creative will a person see?','Naming: use a consistent label for date, audience, goal and version.']},
          {heading:'Treat targeting as a hypothesis',body:'Targeting is not a magic list of demographics. Start from customer evidence, location, intent and context. Avoid sensitive or discriminatory targeting. Use only the platform’s permitted options and check current policy before publishing.',bullets:['Define the service area accurately.','Use customer questions and behaviour as evidence.','Keep the test focused enough to interpret.','Do not infer sensitive personal traits.']}
        ],{title:'A practical naming convention',body:'Example: “2026-11_LocalBreakfast_Enquiries_Test01”. A readable name helps the team understand the goal and version later.'},{title:'Draft a campaign map',body:'Sketch campaign → ad set/group → ad. Write the objective, audience hypothesis, location, creative idea and conversion event at the correct level.',steps:['Name the campaign objective.','Describe audience and location.','Write one ad idea and CTA.','Record the conversion event.']},Q('What is the most responsible use of audience targeting?', ['Use sensitive personal information to guess who may buy','Build a testable hypothesis from relevant context and permitted platform controls','Target everyone in the country for a local pickup offer'],1,'Targeting should be relevant, lawful and platform-compliant. It should not use sensitive traits or ignore the service area.')),
        L('Creative, message and landing-page fit','The ad-to-page promise',18,'A good ad earns attention by making a relevant promise. A good landing page continues that promise with useful details. If the two disagree, visitors lose confidence.',[
          {heading:'Use a clear creative brief',body:'State the audience, problem, offer, proof, CTA and limitation before designing. The ad should be understandable quickly, but it must not hide important conditions. Use real product imagery or clearly labelled illustrations; do not fabricate results or testimonials.',bullets:['Hook: a relevant reason to pay attention.','Offer: what is available and for whom.','Proof: accurate details that support the claim.','CTA: a clear next step.','Limitations: dates, availability, eligibility or service area.']},
          {heading:'Keep the journey consistent',body:'Use the same product name, price, location and promise in the ad and on the landing page. Make the CTA work and check page speed, mobile usability and form completion. Measure the full journey rather than stopping at clicks.',bullets:['Ad headline matches the landing-page headline.','Price and terms are visible.','Page loads and works on mobile.','The form asks only for necessary information.','Confirmation tells the visitor what happens next.']}
        ],{title:'Message example',body:'“Breakfast boxes for busy mornings” is only useful if the landing page shows what is inside, price, collection or delivery options and how to order. A catchy claim without details creates friction.'},{title:'Create two message variations',body:'Write two truthful ad hooks for the same offer. Change one main idea at a time and state which audience need each version addresses.',steps:['Write the audience problem.','Draft a benefit-led hook.','Draft an information-led hook.','Make sure both lead to the same accurate offer details.']},Q('What should happen when an ad promises a price?', ['The landing page should make that price and its conditions clear','The price can be hidden until after the form','The page can show a different offer'],0,'The ad and landing page should match. Transparency supports trust and avoids misleading visitors.')),
        L('Budgets, metrics and optimisation','Control the experiment',20,'A budget is a limit on risk, not a guarantee of results. Metrics help diagnose what happened, but each number needs a definition and context.',[
          {heading:'Know the common metrics',body:'Impressions are displays. Clicks are interactions as defined by the platform. CTR is clicks divided by impressions. CPC is spend divided by clicks. CPA is spend divided by defined acquisitions. ROAS is attributed revenue divided by ad spend. None of these alone describes profit.',bullets:['CTR = clicks ÷ impressions × 100.','CPC = spend ÷ clicks.','CPA = spend ÷ defined conversions.','ROAS = attributed revenue ÷ ad spend.','Profit also considers product, delivery, wages, overheads, taxes and other costs.']},
          {heading:'Set decision rules before launch',body:'Decide when you will review the test and what evidence would trigger a change or stop. Avoid changing many variables at once. A low click rate may suggest a message or audience problem; clicks without enquiries may point to landing-page relevance, friction or tracking. These are hypotheses to investigate, not automatic diagnoses.',bullets:['Choose a fixed test window and maximum spend.','Check tracking before interpreting results.','Change one major variable at a time when possible.','Record the reason for every change.','Pause if the offer, page or measurement becomes unreliable.']}
        ],{title:'Worked calculation',body:'If ad spend is ₹1,800 and there are 18 attributed orders, cost per order = ₹1,800 ÷ 18 = ₹100. If those orders produce ₹9,000 attributed revenue, ROAS = ₹9,000 ÷ ₹1,800 = 5×. This is not a 5× profit: other business costs are not subtracted.'},{title:'Create a small test budget',body:'Choose a fictional maximum budget you can afford to lose, the number of days, the review point and a stop condition. Do not present the budget as a forecast.',steps:['Set a maximum total spend.','Set start and end dates.','Choose one review point.','Write what would cause you to pause.']},Q('A campaign reports 5× ROAS. What does that prove?', ['The business earned five times as much profit','Attributed revenue was five times the ad spend under the chosen attribution rules','Every customer will buy again'],1,'ROAS compares attributed revenue with ad spend. It is not net profit and depends on attribution and data quality.'))
      ], final:Q('Clicks increase but qualified enquiries do not. What should you inspect?', ['Only raise the budget','Tracking, audience relevance, ad-to-page match, form friction and lead quality','Hide the enquiry form'],1,'Diagnose the journey and data before spending more. A higher click count does not automatically mean a better business result.')
    },
    6: {
      title:'Content, Blogging & Copywriting', kicker:'TURN USEFUL IDEAS INTO CLEAR MESSAGES', level:'Beginner', duration:'3–4 hours', outcome:'Research, plan, write and improve content that answers audience questions and supports a meaningful goal.',
      project:{title:'Create a one-week content campaign',brief:'Develop a small content set for Maple Lane that answers customer questions about breakfast boxes and makes ordering clearer.',deliverables:['Audience question and content objective','One blog outline','Three social captions in different formats','One CTA and supporting proof','Editing and distribution checklist'],steps:['Collect real questions from the audience.','Choose one question and the best content format.','Write a useful outline before drafting.','Edit for clarity, accuracy and accessibility.','Repurpose the idea only where it remains useful.']},
      glossary:[['Content strategy','A plan for what to create, why, for whom and how it will be maintained.'],['Editorial brief','A document that defines the audience, purpose, angle and requirements of a piece.'],['Hook','An opening that gives the reader a relevant reason to continue.'],['Lead','The opening section of an article or story.'],['CTA','A call to action that gives the reader a relevant next step.'],['Copywriting','Writing intended to help an audience understand and take an action.'],['Repurposing','Adapting an existing idea into another useful format.'],['Alt text','A text alternative that communicates the purpose of an informative image.']],
      lessons:[
        L('Start with audience questions and content purpose','Strategy before writing',16,'Content is useful when it helps a particular audience make progress. Publishing more often does not automatically make content more valuable.',[
          {heading:'Define the job of the content',body:'Choose whether the content should explain, compare, reassure, demonstrate, entertain or help someone act. Then define the audience and the question they have. One piece of content can have a primary job and supporting goals, but it should not try to do everything.',bullets:['Audience: who is this for?','Question: what do they need to know?','Purpose: what should become clearer?','Action: what is the next helpful step?']},
          {heading:'Research before drafting',body:'Look at customer questions, search results, comments, product information and credible primary sources. Record what you know, what you assume and what needs verification. Do not copy another creator’s article or invent statistics to make the content look authoritative.',bullets:['Collect exact audience wording.','Check facts against reliable sources.','Note the date for information that can change.','Ask a subject expert when the claim is technical or high-stakes.']}
        ],{title:'Maple Lane content idea',body:'Instead of “Why our bakery is great”, answer “What is included in a breakfast box, and when should I order?” The second idea reflects a real decision the customer needs to make.'},{title:'Write a content brief',body:'Choose one question and write a brief containing audience, purpose, key points, proof needed, preferred format and next action.',steps:['Write the exact question.','Name the intended reader.','List three useful points.','Identify facts that need verification.']},Q('What should a content brief begin with?', ['A random trending sound','The audience and the question the content should answer','A target word count chosen before research'],1,'Purpose and audience determine the content. Length and format should follow the need, not the other way around.')),
        L('Build a clear blog outline','Structure the answer',18,'A strong article outline helps the reader move from a question to a useful answer. It also keeps the writer from adding unrelated sections just to make the article longer.',[
          {heading:'Write a specific working headline',body:'A headline should make the topic and value clear without promising more than the article delivers. Avoid clickbait, vague claims and exaggerated superlatives. A clear introduction quickly tells readers what the article covers and who it helps.',bullets:['Use the main question naturally.','Make the angle specific.','Do not promise guaranteed results.','Keep the article’s scope realistic.']},
          {heading:'Organise sections in a helpful sequence',body:'Move from the reader’s problem to the explanation, options, examples and practical next step. Use descriptive subheadings. Add a table or checklist when it makes comparison easier. Cut sections that do not help the reader answer the original question.',bullets:['Opening: name the problem and the answer you will provide.','Main sections: explain the steps or decision factors.','Example: show how the idea works in context.','Conclusion: summarise and give a useful next step.']}
        ],{title:'Outline example',body:'Article: “How to Choose a Breakfast Box for a Team Meeting”. Sections: quantity and timing; dietary needs; menu choices; delivery or collection; budget; ordering checklist.'},{title:'Make a five-heading outline',body:'Choose a topic from your own learning. Write a headline and five headings in the order a beginner would need them.',steps:['State the reader’s question.','Write a clear headline.','Arrange five logical headings.','Add one example and a checklist.']},Q('Why is an outline useful?', ['It guarantees search ranking','It organises the answer so readers can follow it','It removes the need to check facts'],1,'An outline improves clarity and completeness. It does not replace research, editing or fact-checking.')),
        L('Write copy that is clear and honest','Hooks, benefits and CTAs',18,'Copywriting is not about tricking people. It is about making an offer understandable, relevant and easy to evaluate.',[
          {heading:'Translate features into benefits',body:'A feature tells what is included; a benefit explains why it may matter. Keep the connection truthful. “Reusable insulated packaging” is a feature. “Helps keep the box warm during the short journey” is a benefit only if that performance is supported.',bullets:['Use customer language where possible.','Prefer concrete details to vague superlatives.','Support claims with evidence.','Mention limits or conditions when they affect the decision.']},
          {heading:'Make the next step clear',body:'A call to action should tell people what happens when they act. “Enquire about group orders” is clearer than “Learn more” when the next step is a conversation about quantity and availability. Avoid fake urgency, hidden fees and confusing button labels.',bullets:['Use action verbs.','Keep one primary CTA prominent.','Explain what happens after the click.','Do not make an action sound easier or faster than it is.']}
        ],{title:'Copy improvement',body:'Vague: “Best breakfast ever!” More useful: “Choose from three breakfast-box options, see ingredient details and enquire about weekday collection.” The second version is specific and avoids unsupported superiority claims.'},{title:'Write three CTA options',body:'Write one CTA for browsing, one for asking a question and one for ordering. For each, explain what the visitor should expect next.',steps:['Write an action-led label.','Explain the next screen or response.','Check that the business can fulfil the promise.']},Q('Which copy is most trustworthy?', ['“Guaranteed to be the best in the city” without evidence','A specific description of what is included, with accurate conditions','“Only two left” when stock is not limited'],1,'Specific, verifiable details help readers decide. Unsupported superiority claims and false scarcity can mislead.')),
        L('Edit, publish and repurpose responsibly','Quality and distribution',17,'A draft is not finished when the last sentence is written. Editing checks whether the content is accurate, understandable, accessible and ready to be maintained.',[
          {heading:'Use a practical editing pass',body:'First check whether the content answers the question. Then check facts, spelling, structure, examples, links, image rights and accessibility. Read the piece aloud to find awkward sentences. Ask someone unfamiliar with the topic to explain the main point back to you.',bullets:['Accuracy: can each important claim be supported?','Clarity: can a beginner follow the explanation?','Structure: do headings guide the reader?','Accessibility: are images, links and tables usable?','Maintenance: who will update it if details change?']},
          {heading:'Repurpose the core idea, not the whole article blindly',body:'One well-researched idea can become a short video, carousel, email answer or FAQ entry. Adapt the level of detail and the platform format. Keep the central facts consistent and link to the fuller resource when it helps.',bullets:['Keep the original source notes.','Adapt the hook to the audience and format.','Check whether the new version still includes necessary context.','Track the response by format and objective.']}
        ],{title:'A useful repurposing example',body:'A detailed article about ingredients can become a carousel listing options, a short video showing preparation and a FAQ answer about allergens. The facts stay consistent, while each format serves a different moment.'},{title:'Create a quality checklist',body:'Before publishing, write five checks you will perform every time. Include one accuracy check and one accessibility check.',steps:['Check claims and sources.','Preview on a phone.','Test links and CTA.','Check image rights and text alternatives.','Set a review date for information that may change.']},Q('What is responsible repurposing?', ['Copying the article into every platform with no changes','Adapting the idea to the new format while preserving accuracy and context','Removing source notes'],1,'Repurposing should make the idea useful in a new context without stripping away important information or attribution.'))
      ], final:Q('You have one reliable article and a small audience. What is a sensible next step?', ['Repurpose the core idea into a format that answers another audience question','Publish ten unrelated posts immediately','Change the facts to make each version more exciting'],0,'A useful idea can be adapted to different formats while facts and context remain consistent.')
    },
    7: {
      title:'Email & Automation', kicker:'SEND RELEVANT MESSAGES WITH PERMISSION', level:'Beginner', duration:'3–4 hours', outcome:'Plan permission-based email communication, segments, useful messages and simple automated journeys.',
      project:{title:'Design a welcome email sequence',brief:'Plan a consent-based welcome sequence for people who voluntarily request updates from Maple Lane Home Bakery.',deliverables:['Signup purpose and consent wording','Audience segment and entry rule','Three-email sequence outline','Unsubscribe and preference approach','Measurement and quality checklist'],steps:['Define why someone would sign up.','Ask for clear permission and explain frequency.','Create a useful welcome email.','Add follow-ups only when they serve the subscriber.','Test links, mobile rendering and unsubscribe behaviour.']},
      glossary:[['Opt-in','A person actively agreeing to receive a type of communication.'],['Consent','A clear, informed permission for a stated purpose.'],['Segment','A group of contacts with a relevant shared characteristic or behaviour.'],['Automation','A workflow that sends or performs an action when defined conditions occur.'],['Bounce','An email that could not be delivered.'],['Unsubscribe','A request to stop receiving a particular communication.'],['Open rate','A platform-reported estimate of opens; privacy features can affect accuracy.'],['Click rate','A measure of tracked email link clicks, defined by the reporting system.']],
      lessons:[
        L('Permission is the foundation','Respect the inbox',17,'An email address is not permission to send marketing. People should understand what they are signing up for, what kind of messages they will receive and how they can stop them.',[
          {heading:'Ask clearly and separately',body:'Use a clear signup explanation and an unchecked choice where appropriate. Do not bundle marketing permission into a purchase or disguise it inside unrelated terms. Keep a record of when and how permission was collected, and use the address only for the explained purpose.',bullets:['Say what type of email will be sent.','Set a realistic frequency expectation.','Do not add purchased or scraped lists.','Make unsubscribe easy to find and use.']},
          {heading:'Protect the list',body:'Collect only what is needed. Limit access, use a reputable email service and keep a process for removing or correcting information. Follow the rules that apply to the audience and location; this learning material is not legal advice.',bullets:['Avoid asking for unnecessary personal details.','Do not expose recipient addresses to other subscribers.','Keep a record of permission and opt-outs.','Review the provider’s security and data practices.']}
        ],{title:'Good signup example',body:'“Get occasional menu updates and seasonal offers from Maple Lane. We usually email once or twice a month. You can unsubscribe at any time.” The exact frequency should match what the business can actually deliver.'},{title:'Write a clear signup form',body:'Draft the signup description, what the subscriber will receive, expected frequency and opt-out explanation. Do not pre-tick the marketing consent box.',steps:['Name the message purpose.','State the expected frequency.','Use a separate clear permission choice.','Explain how to unsubscribe.']},Q('Which list-building method is appropriate?', ['Buy a large list from an unknown seller','Add every customer automatically without explaining it','Invite people to opt in clearly and record their permission'],2,'Permission should be clear and verifiable. Purchased and scraped addresses create trust, compliance and deliverability risks.')),
        L('Segment subscribers and set useful goals','Relevance over volume',16,'Segmentation means grouping subscribers so messages are more relevant. The purpose is not to collect endless personal data; it is to send fewer, more useful messages.',[
          {heading:'Choose a segment that changes the message',body:'Possible segments include people who requested a menu, subscribers who selected a product interest or customers who explicitly asked for event updates. A segment is useful only if it changes what you send or when you send it.',bullets:['Use information people knowingly provided.','Keep categories understandable and useful.','Avoid sensitive inferences.','Let subscribers update preferences where practical.']},
          {heading:'Define one email objective',body:'A single email should have a clear purpose: welcome a subscriber, share a requested menu, explain a new service or confirm an action. Define the useful click or response before writing. More links can dilute the message and confuse the reader.',bullets:['One main message.','One primary CTA.','Relevant supporting information.','A clear sender name and subject line.']}
        ],{title:'Maple Lane segment example',body:'A subscriber who asked for vegetarian options could receive a message about the vegetarian menu. A person who signed up only for event updates should not automatically receive unrelated promotions.'},{title:'Create two segments',body:'Write two segments based on explicit preferences and define the one thing each segment needs to receive. Explain why the data is appropriate to use.',steps:['Choose two clear interests.','Define how a person chooses each interest.','Write one relevant message for each segment.','List data you will not collect because it is unnecessary.']},Q('When is segmentation useful?', ['When it helps send a more relevant message based on appropriate information','When it creates as many categories as possible','When it guesses sensitive traits'],0,'Segments should improve relevance and respect the subscriber. Collecting unnecessary data or making sensitive guesses is not a good practice.')),
        L('Write a helpful email','Subject, body and CTA',18,'A good email respects the reader’s time. It makes the sender, purpose and next step clear, and it works on a phone.',[
          {heading:'Build a simple email structure',body:'A useful email usually includes a recognisable sender, a clear subject, a short opening, the key information, one primary action and a proper footer. Put the important detail near the beginning. Avoid misleading subject lines.',bullets:['Subject: specific and honest.','Preheader: a helpful preview, not a repeated slogan.','Opening: remind readers why they are receiving this.','Body: give the promised information.','CTA: make the next step obvious.','Footer: include business details and unsubscribe options required by the service and applicable rules.']},
          {heading:'Write for mobile reading',body:'Use short paragraphs, meaningful headings and readable text. Do not rely only on images to communicate essential information. Check that the email is understandable with images disabled and that links are descriptive.',bullets:['Keep the main message near the top.','Use a single-column layout when appropriate.','Check text size and contrast.','Test every link and CTA.']}
        ],{title:'Subject line rewrite',body:'Vague: “Important update”. Clearer: “This week’s breakfast menu and collection times”. The clearer subject helps the subscriber decide whether the email is relevant.'},{title:'Draft a welcome email',body:'Write a subject line, two-sentence welcome, what the subscriber will receive, one useful link and a clear unsubscribe explanation.',steps:['Confirm why the person signed up.','Write an accurate subject.','Deliver the promised value.','Use one clear CTA.']},Q('Which subject line is most respectful?', ['“URGENT!!! Open immediately” for a routine menu update','“This week’s menu and collection times”','A false “Re:” subject pretending to be a reply'],1,'A subject should accurately describe the content. Misleading urgency and fake reply prefixes damage trust.')),
        L('Simple automation and responsible measurement','Test the journey',19,'Automation sends a message when a defined event or condition occurs. It can improve timing, but a poorly designed workflow can send irrelevant or repeated messages.',[
          {heading:'Map the trigger and the exit',body:'A welcome flow might start after a person confirms a signup. Before adding messages, define the trigger, waiting period, audience, message purpose and exit condition. People who unsubscribe or no longer meet the rule should not continue receiving the sequence.',bullets:['Trigger: what event starts the workflow?','Delay: when should the next message arrive?','Condition: who should receive it?','Exit: when should the workflow stop?','Fallback: what happens if the person does not act?']},
          {heading:'Interpret email metrics carefully',body:'Delivery, bounce, unsubscribe, click and conversion measures can inform decisions. Open rates are increasingly imperfect because privacy and security systems may load tracking images automatically or obscure activity. Do not treat an open as proof a human read the email.',bullets:['Check bounce and complaint signals.','Use meaningful clicks and completed actions where appropriate.','Compare similar campaigns and audiences.','Test one change at a time.','Stop a workflow if it sends the wrong or repeated message.']}
        ],{title:'Three-step welcome flow',body:'Email 1 confirms signup and delivers the promised menu. Email 2, after a reasonable delay, shares helpful ordering tips. Email 3 offers an optional preference choice. Every message stops when the person unsubscribes.'},{title:'Draw a simple flow',body:'Write a three-message flow with trigger, delay, purpose and exit conditions. Add a test case for someone who unsubscribes after the first message.',steps:['Define a confirmed signup trigger.','Write the purpose of each email.','Set a sensible delay.','Add unsubscribe and suppression checks.']},Q('What should happen when a subscriber opts out?', ['The workflow should keep sending because it was automated','The person should be suppressed from future marketing messages in that workflow','The system should add them to another list'],1,'Automation must respect opt-outs. Suppression and exit rules are core parts of a responsible workflow.'))
      ], final:Q('A welcome automation sends an offer to someone who only requested a receipt. What is the correct fix?', ['Keep sending because they are already in the database','Review the signup purpose, permission rule and workflow trigger; stop inappropriate sends','Hide the unsubscribe link'],1,'The workflow must match the permission and purpose the person actually agreed to. Correct the trigger and audience rules.')
    },
    8: {
      title:'Affiliate Marketing & Monetisation', kicker:'EARN TRUST BEFORE YOU EARN COMMISSION', level:'Beginner', duration:'2–3 hours', outcome:'Understand affiliate relationships, choose relevant offers and create transparent content with clear disclosures.',
      project:{title:'Plan an ethical affiliate content page',brief:'Create a comparison guide for a fictional audience. The aim is to help readers make an informed choice, with transparent disclosure if a commercial relationship exists.',deliverables:['Audience need and selection criteria','Shortlist with evidence and limitations','Comparison table','Disclosure wording near recommendations','Tracking and review plan'],steps:['Define the reader’s decision.','Choose fair comparison criteria.','Research claims using current primary sources.','Disclose material relationships clearly and prominently.','Update or remove recommendations when information changes.']},
      glossary:[['Affiliate','A publisher or partner who refers an audience to another business.'],['Merchant','The business offering the product or service.'],['Commission','Payment earned under a defined referral or sale arrangement.'],['Referral link','A link that identifies a referral source or partner.'],['Conversion window','The period in which an action may be credited to a referral, as defined by the programme.'],['Disclosure','A clear explanation of a material relationship or commercial benefit.'],['Attribution','The rule used to assign credit for a conversion.'],['Cookie duration','The period a tracking cookie may remain active, subject to browser and programme rules.']],
      lessons:[
        L('How affiliate marketing works','The relationship',15,'Affiliate marketing is a commercial arrangement in which a publisher refers an audience to a merchant and may earn a commission when a defined action occurs. It is not free money; it depends on audience trust, useful content and programme terms.',[
          {heading:'Understand the three parties',body:'The audience wants help making a decision. The publisher creates content or recommendations. The merchant supplies the product or service and defines programme terms. The tracking system records eligible referrals according to those terms.',bullets:['Audience: needs accurate information and a suitable offer.','Publisher: needs to create useful, honest content.','Merchant: sets product, terms and commission rules.','Tracking: assigns credit under programme conditions.']},
          {heading:'Commission does not prove quality',body:'A high commission does not mean a product is right for the audience. Compare suitability, price, reliability, support, limitations and alternatives. Be willing to recommend no product when evidence is weak.',bullets:['Read the programme terms before joining.','Check restrictions on traffic sources and brand bidding.','Understand the return, refund and cancellation rules.','Do not make claims you cannot support.']}
        ],{title:'Decision-first example',body:'A student wants a beginner laptop for video editing. A useful comparison explains performance needs, memory, warranty and budget trade-offs. It does not automatically recommend whichever product pays the highest commission.'},{title:'Map the relationship',body:'Draw audience → content/publisher → merchant. Add the referral tracking step and list what each party expects.',steps:['Write the audience decision.','Describe the content you will create.','Identify the merchant and programme rules.','Explain how a referral may be tracked.']},Q('What should guide an affiliate recommendation?', ['The highest commission only','The reader’s needs, evidence, suitability and transparent terms','A product the publisher has never checked'],1,'Recommendations should serve the audience. Commission is a commercial consideration, not proof that a product is suitable.')),
        L('Choose relevant programmes and products','Fit before commission',16,'A programme is useful only when its products suit your audience and you can create honest, helpful information about them.',[
          {heading:'Evaluate the product and the programme',body:'Review product quality, availability, total price, support, return conditions, merchant reputation and whether the audience can realistically use it. Read the programme agreement for payout timing, eligible conversions, exclusions, tracking windows and prohibited promotion methods.',bullets:['Audience relevance and genuine need.','Current product specifications and price.','Merchant support and return process.','Commission structure and payout threshold.','Allowed channels and restricted claims.']},
          {heading:'Be careful with platform and market changes',body:'Affiliate links, tracking rules and programme terms can change. Check the merchant’s current documents before publishing. Do not rely on screenshots from old tutorials as proof of today’s policy.',bullets:['Record when you checked key information.','Use approved links and assets.','Avoid link cloaking that hides the destination where disclosure or policy requires clarity.','Review broken links and discontinued products.']}
        ],{title:'Maple Lane analogy',body:'If the bakery recommends a local reusable lunch container, it should compare size, material, cleaning and suitability—not select it only because the referral rate is high.'},{title:'Create a selection scorecard',body:'Choose three criteria that matter to your audience and score two hypothetical products. Explain missing evidence rather than guessing.',steps:['Define the audience and use case.','Select three decision criteria.','Compare two options using current evidence.','Record limitations and missing details.']},Q('What should you check before joining an affiliate programme?', ['Only the banner designs','Commission terms, eligibility, tracking, product suitability and promotion rules','Whether someone online said it pays well'],1,'The agreement and product experience determine whether the programme is appropriate. Understand the conditions before promoting it.')),
        L('Disclosures and honest recommendations','Trust and transparency',18,'If you have a material connection to a product or receive value for talking about it, people should be able to recognise that relationship clearly. Disclosure is part of the content, not a hidden footer detail.',[
          {heading:'Make the relationship obvious',body:'A disclosure should be clear, easy to notice and close to the recommendation. Use plain language such as “This page contains affiliate links. I may earn a commission if you buy through them, at no extra cost to you.” Adapt the wording to the real arrangement and applicable rules.',bullets:['Place the disclosure before or near the relevant recommendation.','Use a clear label, not an ambiguous hashtag alone.','Disclose free products, discounts or other material benefits when required.','Do not assume a platform tool replaces every required disclosure.']},
          {heading:'Separate facts, experience and opinion',body:'Label what you personally tested, what the manufacturer states and what you infer. If you have not used the product, say so. Avoid fake reviews, fabricated results and unsupported health, financial or performance claims.',bullets:['Fact: verify with a current primary source.','Experience: state what you actually observed.','Opinion: make it clear that it is your judgement.','Limitation: explain who the product may not suit.']}
        ],{title:'Disclosure example',body:'“Disclosure: Some links below are affiliate links. If you purchase through them, I may receive a commission. This does not change the price you pay. I selected these options using the criteria described below.” Only use wording that accurately describes the arrangement.'},{title:'Write a transparent recommendation',body:'Draft a recommendation with a disclosure, two reasons it may suit a reader, one limitation and one alternative.',steps:['Write a plain-language disclosure.','List evidence-based reasons.','Add a limitation.','State whether you personally tested it.']},Q('Where should an affiliate disclosure appear?', ['Hidden at the bottom of a long page','Clearly and prominently near the recommendation or link','Only in a private message'],1,'The relationship should be recognisable when the audience encounters the recommendation. Check applicable local guidance too.')),
        L('Build content and review performance','Useful content over link drops',17,'An affiliate page should help people decide, even when the reader does not buy. Useful comparison criteria, explanations and limitations create more value than a list of links.',[
          {heading:'Create decision-support content',body:'Possible formats include comparison guides, setup tutorials, use-case reviews, checklists and alternatives. Explain how options were selected and which reader each option may suit. Keep the content current when prices, availability or features change.',bullets:['Start with the reader’s decision criteria.','Explain how the shortlist was made.','Compare like with like.','Include disadvantages and alternatives.','Link to the merchant for current details.']},
          {heading:'Interpret affiliate measures',body:'Clicks show that someone followed a link; they do not prove a purchase. Conversion rate depends on the programme’s defined denominator and attribution rules. Earnings per click or commission totals need context such as refunds, cancellations, audience source and time period.',bullets:['Track clicks by content and placement.','Check approved conversions and reversals.','Use a consistent date range.','Do not claim every conversion was caused by one page if attribution rules do not support that conclusion.']}
        ],{title:'A better comparison table',body:'Compare price, key features, support, limitations and best-fit reader. State the date checked. A “best for everyone” label is rarely useful because audience needs differ.'},{title:'Draft a comparison outline',body:'Create a comparison table for two fictional options. Add one “best fit” and one limitation for each, plus a review date.',steps:['Write the decision the reader is making.','Choose consistent comparison criteria.','Add evidence and a checked date.','Write the limitations and disclosure.']},Q('What does a high affiliate click count prove?', ['That all visitors purchased','That every purchase was profitable','Only that many tracked link clicks occurred under the tracking definition'],2,'Clicks are an intermediate event. Purchases, approvals, reversals and earnings are separate outcomes.'))
      ], final:Q('You receive a free product and publish a recommendation. What is important?', ['Disclose the material relationship clearly and give an honest, evidence-based assessment','Pretend you bought it yourself','Mention only positive features'],0,'A material relationship should be disclosed, and the assessment should remain accurate—including limitations.')
    },
    9: {
      title:'Analytics & Data Decisions', kicker:'TURN MEASUREMENT INTO BETTER QUESTIONS', level:'Beginner', duration:'3–4 hours', outcome:'Create a basic measurement plan, understand events and metrics, interpret reports and make cautious decisions.',
      project:{title:'Create a measurement plan',brief:'Build a simple measurement plan for the Maple Lane website and campaign. Define what should be measured, how it is named and what decision the data could support.',deliverables:['Business goal and measurement question','Event and parameter definitions','UTM naming rules','KPI calculation with denominator','Data-quality and privacy checklist'],steps:['Write the business question first.','Define each event and what triggers it.','Choose a small set of supporting metrics.','Test the events and campaign tags.','Review the data quality before making decisions.']},
      glossary:[['Event','A recorded interaction or occurrence, defined by a measurement system.'],['Parameter','Additional information describing an event.'],['Key event','An event marked as important to a business outcome in GA4.'],['Metric','A quantitative measurement.'],['Dimension','An attribute used to describe or break down data.'],['UTM','A query-string tag used to identify campaign traffic sources and details.'],['Attribution','A rule for assigning credit to marketing touchpoints.'],['Conversion rate','The number of defined conversions divided by a clearly stated denominator, multiplied by 100.']],
      lessons:[
        L('Start with a business question','Measurement planning',16,'Analytics should help someone make a decision. Collecting every available number creates noise if no one knows what question the numbers should answer.',[
          {heading:'Move from goal to measure',body:'Start with a business goal, then write a question that could help guide action. For example: “Are visitors from the menu page completing the enquiry form?” This is more useful than “How many page views did we get?” Define the event and population before choosing a dashboard.',bullets:['Goal: the outcome the business cares about.','Question: what do we need to understand?','Event: what action should be recorded?','Metric: how will we count or calculate it?','Decision: what might we change based on the result?']},
          {heading:'Define the denominator and time window',body:'A percentage is meaningless unless the base group is clear. “Conversion rate” could mean orders divided by visits, enquiries divided by sessions or leads divided by clicks. Write the numerator, denominator, scope and time period every time.',bullets:['Numerator: the events or people counted.','Denominator: the group being compared.','Scope: page, channel, campaign or audience.','Time window: the dates used.']}
        ],{title:'Worked example',body:'60 enquiries from 1,000 website visits = 60 ÷ 1,000 × 100 = 6%. That is the visit-to-enquiry rate for this example and time window—not a universal benchmark.'},{title:'Write one measurement brief',body:'Choose a business goal and write one measurement question, the event, numerator, denominator, time period and decision it may inform.',steps:['Choose a measurable business goal.','Write the question in plain language.','Define numerator and denominator.','Write one possible decision.']},Q('What must accompany a conversion-rate percentage?', ['A colour label','A clearly defined numerator, denominator and time window','A claim that every visitor is identical'],1,'A percentage needs a defined base and scope. Otherwise people may compare incompatible calculations.')),
        L('Events, parameters and key actions','What is being recorded?',17,'Modern analytics tools often record events: named interactions that happen on a site or app. The event name says what happened; parameters provide context.',[
          {heading:'Design an event thoughtfully',body:'An event should represent a meaningful action and have a clear trigger. For example, “generate_lead” might fire after a valid enquiry is submitted, not merely when someone opens the form. Parameters can describe form type or page context, but should not contain unnecessary personal information.',bullets:['Name the event consistently.','Define the exact trigger.','Add only useful parameters.','Avoid collecting personal or sensitive data without a valid basis.','Test that it fires once and at the right moment.']},
          {heading:'Distinguish events, parameters and metrics',body:'An event records an occurrence. A parameter gives details about it. A metric counts or calculates something from the data. A dimension describes a category used to break down reports. A key event is an event marked as especially important in GA4. Product terminology can change, so check current documentation.',bullets:['Event: form_submit.','Parameter: form_name = breakfast_enquiry.','Metric: count of valid form submissions.','Dimension: source/medium or page path.']}
        ],{title:'Good event definition',body:'Event: “enquiry_submit”. Trigger: a successful server-confirmed or validated form submission. Not a button click, because a click may occur even if the form fails.'},{title:'Create an event dictionary',body:'Define three website events with a name, trigger, purpose and any needed non-personal parameters. Include one event you deliberately will not track and why.',steps:['Choose three meaningful actions.','Write the exact trigger for each.','Name useful context parameters.','Check privacy and duplicate-firing risks.']},Q('When should a lead event fire?', ['Whenever the enquiry button is visible','When a valid enquiry is successfully submitted','Every time the page loads'],1,'The event should represent the meaningful completed action, not an earlier opportunity to take it.')),
        L('Campaign tracking with UTMs','Know where visits came from',15,'Campaign tags help distinguish visits generated by different marketing activities. Consistent naming is more important than inventing many parameters.',[
          {heading:'What UTM tags do',body:'UTM parameters are added to a URL to identify campaign context. Common labels include source, medium, campaign, term and content. A source might be a platform or newsletter; medium describes the channel type; campaign identifies the initiative. Use lowercase and a shared naming rule.',bullets:['utm_source: the source, such as instagram or newsletter.','utm_medium: the medium, such as social or email.','utm_campaign: the campaign name.','utm_content: a version or placement when needed.','utm_term: a paid keyword or defined term when appropriate.']},
          {heading:'Avoid messy or sensitive tracking',body:'Do not put names, email addresses, phone numbers or other personal data into URLs. Avoid inconsistent spellings and spaces. Decide the naming convention before links are published, and keep a simple campaign register.',bullets:['Use lowercase and underscores or hyphens consistently.','Do not invent a new name for the same source each week.','Test that the tagged URL loads correctly.','Never include personal information in UTM values.']}
        ],{title:'Example tagged link',body:'A newsletter link could use source=newsletter, medium=email and campaign=november_menu. The actual URL should be checked before it is sent, and the values should match the team’s naming guide.'},{title:'Create a UTM naming rule',body:'Write the UTM values for one social post and one email campaign. Check that both use a consistent style and contain no personal information.',steps:['Choose source and medium.','Create a readable campaign name.','Add content only if it distinguishes a useful variation.','Test each final URL.']},Q('Which information should never be placed in a UTM parameter?', ['A campaign label','A source name','A person’s email address'],2,'URLs can be shared and stored in many systems. Do not place personal information in tracking parameters.')),
        L('Read reports and make cautious decisions','From numbers to action',20,'Reports are useful when they help explain a pattern and guide a next step. They can mislead when tracking is incomplete, definitions change or the analyst assumes correlation proves cause.',[
          {heading:'Use a simple analysis routine',body:'Check the date range, comparison period, filters, event definitions and tracking status before interpreting results. Segment by a useful dimension only when it answers the question. Look for both volume and quality.',bullets:['What changed?','For whom or which source did it change?','What else changed at the same time?','Is the sample large and reliable enough?','What would we test next?']},
          {heading:'Be careful with attribution and causality',body:'Attribution assigns credit according to a model; it does not reveal a perfect history of influence. A customer may see several channels before acting. A campaign may coincide with a sales increase for other reasons. State what the data shows and what it cannot prove.',bullets:['Distinguish observed data from interpretation.','Mention missing or sampled data where known.','Do not double-count the same outcome across systems.','Use experiments when you need stronger causal evidence.']}
        ],{title:'A cautious insight',body:'“Enquiries from the newsletter increased during this period” is an observation. “The newsletter caused all the increase” is a causal claim and needs stronger evidence.'},{title:'Write a three-line report',body:'Write one observation, one possible explanation and one next test. Label the explanation as a hypothesis rather than a proven cause.',steps:['State the change and period.','Name the segment or metric definition.','Offer one cautious hypothesis.','Propose a test or data-quality check.']},Q('Which report statement is most responsible?', ['The campaign caused every sale','Enquiries increased 12% in this period; we will check lead quality and other changes before attributing the rise','The chart looks good, so the campaign is profitable'],1,'A responsible report separates observation from explanation and identifies what still needs verification.'))
      ], final:Q('A dashboard shows a sudden jump in leads. What should you check first?', ['Celebrate and increase spend immediately','Verify the event trigger, duplicates, filters and lead quality before interpreting the jump','Delete the previous data'],1,'A tracking change or duplicate firing can create a false increase. Validate data quality before making a decision.')
    },
    10: {
      title:'Freelancing & Career Capstone', kicker:'TURN SKILLS INTO A CLEAR PROFESSIONAL OFFER', level:'Beginner', duration:'3–5 hours', outcome:'Package beginner skills honestly, scope a small project, communicate with a client and present a portfolio case study.',
      project:{title:'Build your first honest portfolio case study',brief:'Use the fictional Maple Lane Home Bakery project to demonstrate your thinking. Clearly label it as a practice project, not paid client work.',deliverables:['Short profile and skill focus','Fictional client brief and assumptions','Audience and business problem','Recommended plan and sample deliverables','Measurement, risks and reflection'],steps:['Choose a focused service you can currently deliver.','Write the client problem and your assumptions.','Show your process and a realistic sample output.','Explain how success could be measured.','Label the work as a fictional practice project.']},
      glossary:[['Freelancer','A self-employed professional who provides services to clients.'],['Scope','The defined work, boundaries and deliverables of a project.'],['Deliverable','A specific output the client receives.'],['Discovery call','A conversation used to understand a potential client’s needs and fit.'],['Proposal','A document outlining the problem, approach, deliverables, schedule and price.'],['Revision','A requested change to work within agreed boundaries.'],['Portfolio','A curated set of work that demonstrates skills and reasoning.'],['Case study','A structured explanation of a problem, process, output and learning.']],
      lessons:[
        L('Choose a service you can deliver honestly','Skill and fit',16,'Freelancing is not simply creating a profile and waiting for clients. It is a professional service relationship. Start with a task you can perform reliably and explain clearly.',[
          {heading:'Separate interest, skill and proof',body:'You may be interested in SEO, but a client needs to know what you can actually deliver today. Choose a narrow service such as a basic on-page review, a content calendar draft or a monthly report template. Do not claim advanced expertise before you have the skills and evidence.',bullets:['Interest: what you enjoy learning.','Skill: what you can currently do.','Proof: a sample or project demonstrating the skill.','Boundary: what you cannot yet deliver.']},
          {heading:'Create a specific service description',body:'A useful service description names the audience, problem, deliverable and exclusions. “I do digital marketing” is too broad. “I prepare a one-week social content calendar for local businesses, including post ideas, captions and a measurement checklist” is more concrete.',bullets:['Who is it for?','What problem does it address?','What exactly will the client receive?','What is outside the scope?']}
        ],{title:'Beginner-safe service',body:'A beginner may offer a draft content calendar based on a client-approved brief, while clearly excluding paid-ad management, guaranteed reach or revenue claims until qualified and equipped to do that work.'},{title:'Write your service statement',body:'Describe one service in two sentences. Include one deliverable and one boundary so a client understands what is and is not included.',steps:['Name one target client type.','Describe one problem.','List the deliverable.','Write one clear exclusion.']},Q('What is the best beginner freelance offer?', ['“I can guarantee viral growth for any business”','A narrow service with clear deliverables and honest limits','A long list of tools you have opened once'],1,'A specific offer is easier to understand and deliver. Honest limits protect both the freelancer and client.')),
        L('Build a portfolio that shows your thinking','Proof without exaggeration',17,'A portfolio should help someone understand how you approach a problem. It can include practice work, provided it is labelled honestly and does not imply a real client relationship that never existed.',[
          {heading:'Use a clear case-study structure',body:'Explain the context, problem, audience, assumptions, approach, deliverables and what you learned. Show selected screenshots or sample outputs only when you have permission or created them yourself. A practice case study should say that the business and data are fictional.',bullets:['Context: what is the scenario?','Problem: what needs improvement?','Process: how did you reason and research?','Output: what did you create?','Reflection: what would you test or improve next?']},
          {heading:'Show quality, not inflated claims',body:'Do not invent clients, testimonials, revenue increases or performance data. If you used sample numbers, label them illustrative. If a result has not been measured, say so. A clear explanation of a thoughtful process is stronger than a fabricated success story.',bullets:['Label practice projects clearly.','Credit sources and assets.','Remove personal or confidential data.','Explain your own contribution.','Keep samples current and relevant.']}
        ],{title:'Portfolio case-study title',body:'“Practice project: A local bakery website and enquiry journey” tells a visitor what the work is and avoids suggesting a paid engagement.'},{title:'Draft a case study',body:'Write a 150–250 word summary with context, problem, approach, sample deliverable and reflection. Include an explicit practice-project label.',steps:['Write the scenario and audience.','Describe the problem.','Show one piece of work.','Explain the reasoning.','State that no real client results are claimed.']},Q('How should a fictional practice project be presented?', ['As a paid client success story','As a practice case study with fictional details clearly labelled','With invented testimonials to make it credible'],1,'Honesty about the status and data is essential. A practice project can still demonstrate useful reasoning.')),
        L('Discovery, scope and proposals','Set expectations early',18,'A proposal should show that you understand the problem and can define a manageable piece of work. Clear boundaries prevent misunderstandings and unplanned extra work.',[
          {heading:'Ask useful discovery questions',body:'Ask what the business wants to improve, who the audience is, what has already been tried, what resources exist, who approves work and what a successful outcome would look like. Do not promise results you cannot control.',bullets:['What problem should this project solve?','Who is the audience?','What access and materials will be provided?','Who approves content and by when?','What is out of scope?']},
          {heading:'Write the scope in plain language',body:'A proposal should list deliverables, format, timeline, responsibilities, number of revision rounds, price and payment milestones. State assumptions and exclusions. For contracts, tax, consumer, data and intellectual-property questions, use current professional guidance relevant to your location.',bullets:['Deliverable: a specific file or service.','Timeline: dates and client dependencies.','Revisions: what changes are included.','Exclusions: work that needs a separate agreement.','Approval: who signs off and how.']}
        ],{title:'Scope example',body:'“One 7-day content calendar with 5 post concepts, draft captions and a basic measurement checklist. Includes one consolidated revision round. Does not include photography, ad spend, posting or community management.”'},{title:'Draft a one-page proposal',body:'Write the problem, approach, deliverables, timeline, client responsibilities, exclusions and price placeholder. Explain what happens if the project changes.',steps:['Summarise the client problem.','List outputs and format.','Set timeline and approval dates.','State revisions and exclusions.','Add a price and payment schedule placeholder.']},Q('Why should a proposal list exclusions?', ['To make the project confusing','To show what is not included and prevent scope misunderstandings','To avoid explaining the deliverables'],1,'Exclusions make boundaries clear and reduce the risk of unpaid extra work or mismatched expectations.')),
        L('Communicate, deliver and learn professionally','Workflow and capstone',20,'Freelance work depends on communication as much as technical skill. A simple process helps you deliver consistently and maintain a good working relationship.',[
          {heading:'Use a repeatable workflow',body:'A simple workflow includes enquiry, fit check, discovery, proposal, agreement, kickoff, draft, review, final handover and follow-up. Keep decisions and approvals written down. Share progress before a deadline becomes a surprise.',bullets:['Confirm the brief and required access.','Agree on timeline and review dates.','Send a progress update when appropriate.','Keep files organised and named clearly.','Confirm handover and outstanding items.']},
          {heading:'Report results with context',body:'A report should show what was delivered, what was measured, the definition and date range of each metric, what changed and what remains uncertain. Do not claim causality or profit when the data does not support it.',bullets:['Restate the objective.','List deliverables completed.','Define metrics and time period.','Separate observations from interpretation.','Recommend one practical next step.']}
        ],{title:'Capstone scenario',body:'Maple Lane asks for “more orders”. Your task is to clarify whether the priority is group enquiries, weekday pickup or online orders, then propose one measurable first project instead of promising everything at once.'},{title:'Present your capstone',body:'Create a one-page presentation with the client problem, audience insight, proposed approach, deliverables, measures, risks and next step. Label it as a fictional learning project.',steps:['Clarify the business problem.','State assumptions and evidence.','Show the chosen strategy and deliverables.','Define measurement and limitations.','Reflect on what you would learn next.']},Q('What does a professional handover include?', ['Only a message saying “done”','The agreed deliverables, file locations, decisions, remaining actions and relevant metric definitions','A guarantee that business results will continue forever'],1,'A good handover makes the work understandable and actionable. It does not promise outcomes outside the freelancer’s control.'))
      ], final:Q('A client asks for guaranteed first-page Google ranking. What should you do?', ['Promise it to win the project','Explain that rankings cannot be guaranteed, describe the work you can control and agree on realistic measures','Use hidden text to force results'],1,'Search rankings are not under a freelancer’s control. Explain the process, risks, realistic deliverables and measures honestly.')
    }
  };
})();
